          "additionalProperties": false,
          "properties": {
            "current": {
              "type": "number",
              "minimum": 0
            },
            "total": {
              "type": "number",
              "exclusiveMinimum": 0
            },
            "unit": {
              "$ref": "#/$defs/unit"
            }
          }
        },
        "steps": {
          "type": "array",
          "maxItems": 12,
          "items": {
            "type": "object",
            "required": [
              "label",
              "state"
            ],
            "additionalProperties": false,
            "properties": {
              "label": {
                "$ref": "#/$defs/label"
              },
              "state": {
                "type": "string",
                "enum": [
                  "pending",
                  "running",
                  "waiting",
                  "succeeded",
                  "failed",
                  "cancelled",
                  "skipped"
                ]
              }
            }
          }
        },
        "updatedAt": {
          "type": "string",
          "format": "date-time"
        }
      }
    },
    "option": {
      "type": "object",
      "required": [
        "id",
        "label"
      ],
      "additionalProperties": false,
      "properties": {
        "id": {
          "type": "string",
          "pattern": "^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$"
        },
        "label": {
          "$ref": "#/$defs/label"
        },
        "description": {
          "$ref": "#/$defs/text"
        }
      }
    },
    "choiceData": {
      "type": "object",
      "required": [
        "prompt",
        "options",
        "action"
      ],
      "additionalProperties": false,
      "properties": {
        "prompt": {
          "$ref": "#/$defs/text"
        },
        "options": {
          "type": "array",
          "minItems": 2,
          "maxItems": 10,
          "items": {
            "$ref": "#/$defs/option"
          }
        },
        "selection": {
          "type": "string",
          "enum": [
            "single",
            "multiple"
          ],
          "default": "single"
        },
        "minSelect": {
          "type": "integer",
          "minimum": 0,
          "maximum": 10
        },
        "maxSelect": {
          "type": "integer",
          "minimum": 1,
          "maximum": 10
        },
        "allowFreeText": {
          "description": "Only for a choice in a message that has ended (a question at the end of a final answer): the user may also answer by sending a normal message (D22). Ignored for the block of an interrupt, whose free-text entry is governed by interrupt.otherInput (D60).",
          "type": "boolean",
          "default": false
        },
        "action": {
          "allOf": [
            {
              "$ref": "action.schema.json#/$defs/actionSpec"
            },
            {
              "properties": {
                "type": {
                  "const": "choice.select"
                }
              }
            }
          ]
        },
        "state": {
          "$ref": "#/$defs/blockState"
        }
      },
      "allOf": [
        {
          "properties": {
            "state": {
              "not": {
                "anyOf": [
                  {
                    "required": [
                      "outcome"
                    ]
                  },
                  {
                    "required": [
                      "values"
                    ]
                  }
                ]
              }
            }
          }
        }
      ]
    },
    "confirmationData": {
      "type": "object",
      "required": [
        "title",
        "severity",
        "action"
      ],
      "additionalProperties": false,
      "properties": {
        "title": {
          "$ref": "#/$defs/label"
        },
        "body": {
          "$ref": "#/$defs/text"
        },
        "severity": {
          "type": "string",
          "enum": [
            "normal",
            "destructive"
          ]
        },
        "details": {
          "type": "array",
          "maxItems": 12,
          "items": {
            "type": "object",
            "required": [
              "label",
              "value"
            ],
            "additionalProperties": false,
            "properties": {
              "label": {
                "$ref": "#/$defs/label"
              },
              "value": {
                "$ref": "#/$defs/scalar"
              },
              "unit": {
                "$ref": "#/$defs/unit"
              },
              "format": {
                "$ref": "#/$defs/valueFormat"
              }
            }
          }
        },
        "confirmLabel": {
          "$ref": "#/$defs/shortLabel"
        },
        "cancelLabel": {
          "$ref": "#/$defs/shortLabel"
        },
        "action": {
          "allOf": [
            {
              "$ref": "action.schema.json#/$defs/actionSpec"
            },
            {
              "properties": {
                "type": {
                  "const": "confirmation.respond"
                }
              }
            }
          ]
        },
        "state": {
          "$ref": "#/$defs/blockState"
        }
      },
      "if": {
        "properties": {
          "action": {
            "properties": {
              "requiresConfirmation": {
                "const": true
              }
            },
            "required": [
              "requiresConfirmation"
            ]
          }
        }
      },
      "then": {
        "properties": {
          "severity": {
            "const": "destructive"
          }
        }
      },
      "allOf": [
        {
          "properties": {
            "state": {
              "not": {
                "anyOf": [
                  {
                    "required": [
                      "selected"
                    ]
                  },
                  {
                    "required": [
                      "values"
                    ]
                  }
                ]
              }
            }
          }
        }
      ]
    },
    "formField": {
      "type": "object",
      "required": [
        "key",
        "label",
        "type"
      ],
      "additionalProperties": false,
      "properties": {
        "key": {
          "$ref": "#/$defs/key"
        },
        "label": {
          "$ref": "#/$defs/label"
        },
        "type": {
          "type": "string",
          "enum": [
            "text",
            "multiline_text",
            "number",
            "integer",
            "date",
            "datetime",
            "boolean",
            "single_select",
            "multi_select"
          ]
        },
        "required": {
          "type": "boolean",
          "default": false
        },
        "options": {
          "type": "array",
          "maxItems": 20,
          "items": {
            "$ref": "#/$defs/option"
          }
        },
        "min": {
          "type": "number"
        },
        "max": {
          "type": "number"
        },
        "maxLength": {
          "type": "integer",
          "minimum": 1,
          "maximum": 2000
        },
        "unit": {
          "$ref": "#/$defs/unit"
        },
        "placeholder": {
          "$ref": "#/$defs/label"
        },
        "help": {
          "$ref": "#/$defs/text"
        },
        "defaultValue": {
          "anyOf": [
            {
              "$ref": "#/$defs/scalar"
            },
            {
              "type": "array",
              "maxItems": 20,
              "items": {
                "type": "string",
                "maxLength": 64
              }
            }
          ]
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "type": {
                "enum": [
                  "single_select",
                  "multi_select"
                ]
              }
            }
          },
          "then": {
            "required": [
              "options"
            ],
            "properties": {
              "options": {
                "minItems": 1
              }
            }
          }
        }
      ]
    },
    "formIntentData": {
      "description": "Describes WHAT input is needed and why; the renderer decides the form layout.",
      "type": "object",
      "required": [
        "fields",
        "action"
      ],
      "additionalProperties": false,
      "properties": {
        "title": {
          "$ref": "#/$defs/label"
        },
        "purpose": {
          "$ref": "#/$defs/text"
        },
        "fields": {
          "type": "array",
          "minItems": 1,
          "maxItems": 12,
          "items": {
            "$ref": "#/$defs/formField"
          }
        },
        "submitLabel": {
          "$ref": "#/$defs/shortLabel"
        },
        "action": {
          "allOf": [
            {
              "$ref": "action.schema.json#/$defs/actionSpec"
            },
            {
              "properties": {
                "type": {
                  "const": "form.submit"
                }
              }
            }
          ]
        },
        "state": {
          "$ref": "#/$defs/blockState"
        }
      },
      "allOf": [
        {
          "properties": {
            "state": {
              "not": {
                "anyOf": [
                  {
                    "required": [
                      "selected"
                    ]
                  },
                  {
                    "required": [
                      "outcome"
                    ]
                  }
                ]
              }
            }
          }
        }
      ]
    },
    "customData": {
      "description": "Host-defined data. The host MUST register a JSON Schema for each custom type on the server and validate against it; this generic shape only enforces size limits.",
      "type": "object",
      "maxProperties": 32
    }
  }
}
'''),
  'generation.schema.json': jsonDecode(r'''
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/zz-howard/chatweave/schemas/v0.1/generation.schema.json",
  "title": "ChatWeave Generation Control (0.1)",
  "description": "Responses of the generation-control endpoints (paths chosen by the host, see docs/protocol.md 4.6): starting a generation returns the assistant message id synchronously (or startRejected while an interrupt is open); stopping is an explicit, idempotent request distinct from disconnecting; a per-conversation query lists messages still being generated so a client killed before it learned the id can re-attach. These are not block actions and do not use the Action protocol.",
  "$defs": {
    "startResponse": {
      "description": "Returned by the host's submit-user-message endpoint BEFORE generation produces output. Resubmitting the same user message id returns the same assistant messageId with replayed=true and never starts a second generation.",
      "type": "object",
      "required": [
        "userMessageId",
        "messageId"
      ],
      "additionalProperties": false,
      "properties": {
        "userMessageId": {
          "description": "Client-generated id of the user message (idempotency key).",
          "$ref": "action.schema.json#/$defs/actionId"
        },
        "messageId": {
          "description": "Server-generated id of the assistant reply.",
          "$ref": "action.schema.json#/$defs/messageId"
        },
        "streamable": {
          "type": "boolean",
          "default": true
        },
        "replayed": {
          "type": "boolean",
          "default": false
        }
      }
    },
    "startRejected": {
      "description": "Returned by the host's submit-user-message endpoint when it refuses to start because the conversation has an open interrupt that this user can answer (docs/protocol.md 4.8 rule 16, D62). The user message is not stored and no generation starts; the client shows the pending card and locks the composer (keeping the draft). Hosts that cannot refuse a submission (e.g. an offline-queued message) instead stop the paused message first and start normally.",
      "type": "object",
      "required": [
        "userMessageId",
        "error",
        "pending"
      ],
      "additionalProperties": false,
      "properties": {
        "userMessageId": {
          "$ref": "action.schema.json#/$defs/actionId"
        },
        "error": {
          "type": "object",
          "required": [
            "code",
            "message"
          ],
          "additionalProperties": false,
          "properties": {
            "code": {
              "type": "string",
              "enum": [
                "interrupt_pending"
              ]
            },
            "message": {
              "type": "string",
              "maxLength": 500
            }
          }
        },
        "pending": {
          "description": "The paused message and its open interrupt.",
          "type": "object",
          "required": [
            "messageId",
            "interruptId"
          ],
          "additionalProperties": false,
          "properties": {
            "messageId": {
              "$ref": "action.schema.json#/$defs/messageId"
            },
            "interruptId": {
              "$ref": "message.schema.json#/$defs/interruptId"
            }
          }
        }
      }
    },
    "stopResponse": {
      "description": "Result of POST .../messages/{messageId}/stop. stopping: generation is being cancelled (also for a paused message: its open interrupt is closed as cancelled / reason 'stopped'); a message.end with status interrupted and error code cancelled follows. already_ended: nothing to stop; use the persisted message.",
      "type": "object",
      "required": [
        "messageId",
        "status"
      ],
      "additionalProperties": false,
      "properties": {
        "messageId": {
          "$ref": "action.schema.json#/$defs/messageId"
        },
        "status": {
          "type": "string",
          "enum": [
            "stopping",
            "already_ended"
          ]
        }
      }
    },
    "activeMessagesResponse": {
      "description": "Result of GET .../conversations/{conversationId}/active-messages: messages that have not ended (streaming or paused). Empty list when there are none. A list because a group conversation may have several generations at once.",
      "type": "object",
      "required": [
        "messages"
      ],
      "additionalProperties": false,
      "properties": {
        "conversationId": {
          "$ref": "action.schema.json#/$defs/messageId"
        },
        "messages": {
          "type": "array",
          "maxItems": 8,
          "items": {
            "type": "object",
            "required": [
              "messageId",
              "lastSeq"
            ],
            "additionalProperties": false,
            "properties": {
              "messageId": {
                "$ref": "action.schema.json#/$defs/messageId"
              },
              "lastSeq": {
                "description": "Last seq emitted so far (0 if none yet).",
                "type": "integer",
                "minimum": 0
              },
              "status": {
                "description": "streaming (default): being generated. paused: waiting for the user to answer an interrupt (docs/protocol.md 4.8); the message is listed until it ends so a client can show the question and resubscribe after answering.",
                "type": "string",
                "enum": [
                  "streaming",
                  "paused"
                ],
                "default": "streaming"
              },
              "replyTo": {
                "description": "Id of the user message this generation answers, so a client can match its pending user message.",
                "$ref": "action.schema.json#/$defs/messageId"
              }
            }
          }
        }
      }
    }
  },
  "oneOf": [
    {
      "$ref": "#/$defs/startResponse"
    },
    {
      "$ref": "#/$defs/startRejected"
    },
    {
      "$ref": "#/$defs/stopResponse"
    },
    {
      "$ref": "#/$defs/activeMessagesResponse"
    }
  ]
}
'''),
  'message.schema.json': jsonDecode(r'''
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/zz-howard/chatweave/schemas/v0.1/message.schema.json",
  "title": "ChatWeave Message (0.1)",
  "description": "A chat message as persisted by the host and synced to clients: an ordered list of content blocks plus a mandatory plain-text fallback. After reconnect or offline, the persisted message (higher rev) always wins over a locally assembled stream state.",
  "type": "object",
  "required": [
    "id",
    "protocolVersion",
    "role",
    "status",
    "blocks",
    "fallbackText",
    "rev",
    "createdAt"
  ],
  "additionalProperties": false,
  "properties": {
    "id": {
      "description": "Message id. User messages: generated by the sending client (UUIDv7 recommended), doubling as the idempotency key for offline queues and retries; the server validates and adopts it unchanged, and the optimistic local copy is reconciled by this same id. Assistant / system messages: server-generated only.",
      "$ref": "action.schema.json#/$defs/messageId"
    },
    "protocolVersion": {
      "type": "string",
      "pattern": "^[0-9]+\\.[0-9]+$"
    },
    "conversationId": {
      "$ref": "action.schema.json#/$defs/messageId"
    },
    "role": {
      "type": "string",
      "enum": [
        "assistant",
        "user",
        "system"
      ]
    },
    "status": {
      "description": "streaming: still being produced. paused: the run is waiting for the user to answer an interrupt (see 'interrupt'); the same message resumes after the answer (docs/protocol.md 4.8). complete: finished normally. interrupted: producer stopped early (crash, cancel, upstream failure, unanswered interrupt expired); content so far is kept. error: nothing usable was produced; fallbackText explains.",
      "type": "string",
      "enum": [
        "streaming",
        "paused",
        "complete",
        "interrupted",
        "error"
      ]
    },
    "blocks": {
      "type": "array",
      "maxItems": 64,
      "items": {
        "$ref": "content-block.schema.json"
      }
    },
    "fallbackText": {
      "description": "Whole-message plain text. Always present, also for status 'error'. Markdown-only clients render just this.",
      "type": "string",
      "maxLength": 16000
    },
    "rev": {
      "description": "Persisted revision. 0 while the message has not ended (streaming or paused checkpoints); 1 when the message is first completed; +1 for every later change (e.g. a choice block resolved).",
      "type": "integer",
      "minimum": 0
    },
    "lastSeq": {
      "description": "Only on checkpoints of a message that has not ended (rev 0): seq of the last event folded into this version. Required while paused. A synced checkpoint replaces local state only if lastSeq >= the locally applied seq; ended messages (rev >= 1) never carry it.",
      "type": "integer",
      "minimum": 1
    },
    "interrupt": {
      "description": "Present exactly while status is 'paused': the one open interrupt the run is waiting on (docs/protocol.md 4.8). Aligned with AG-UI 1.0 Interrupt (RUN_FINISHED outcome 'interrupt').",
      "$ref": "#/$defs/interrupt"
    },
    "createdAt": {
      "type": "string",
      "format": "date-time"
    },
    "completedAt": {
      "type": "string",
      "format": "date-time"
    },
    "metadata": {
      "description": "Opaque host data (e.g. trace ids). Never rendered by the library.",
      "type": "object",
      "maxProperties": 16
    },
    "steps": {
      "description": "Compact run trace (docs/protocol.md 4.7): the steps the assistant took while producing this message, in step.started order. Stored separately from blocks: steps take no block index, are not counted in blockCount and are never part of fallbackText. Each entry holds only id, host-written label, state, duration, an optional host-written one-line summary, the block a step asked the user through (blockId), and for nested steps the enclosing delegate step (parentStepId). Never tool names, sub-agent names, arguments, raw results or model text (including reasoning). Omitted when there were no steps. Checked by the library, not expressible here: step ids are unique within the message; parentStepId names an earlier step of kind 'delegate' (so no cycles); nesting depth <= 3; at most one step is awaiting_user and it is the interrupt's step.",
      "type": "array",
      "maxItems": 64,
      "items": {
        "$ref": "#/$defs/traceStep"
      }
    },
    "view": {
      "description": "RESERVED for the Phase 2 View protocol (layout planning that references block data by id). Must not be emitted in 0.1; clients ignore it.",
      "not": {}
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "status": {
            "enum": [
              "streaming",
              "paused"
            ]
          }
        }
      },
      "then": {
        "properties": {
          "rev": {
            "const": 0
          }
        }
      },
      "else": {
        "not": {
          "required": [
            "lastSeq"
          ]
        },
        "properties": {
          "rev": {
            "minimum": 1
          },
          "steps": {
            "$comment": "Once the message has ended, every step has ended too: the producer emits step.finished for each started step before message.end.",
            "items": {
              "properties": {
                "state": {
                  "enum": [
                    "succeeded",
                    "failed",
                    "cancelled"
                  ]
                }
              }
            }
          },
          "blocks": {
            "items": {
              "properties": {
                "status": {
                  "not": {
                    "const": "pending"
                  }
                }
              }
            }
          }
        }
      }
    },
    {
      "$comment": "A paused message carries exactly one open interrupt, its lastSeq, and exactly one awaiting_user step (the interrupt's step). Any other status carries no interrupt and no awaiting_user step.",
      "if": {
        "properties": {
          "status": {
            "const": "paused"
          }
        },
        "required": [
          "status"
        ]
      },
      "then": {
        "required": [
          "interrupt",
          "lastSeq",
          "steps"
        ],
        "properties": {
          "steps": {
            "contains": {
              "properties": {
                "state": {
                  "const": "awaiting_user"
                }
              },
              "required": [
                "state"
              ]
            },
            "minContains": 1,
            "maxContains": 1
          },
          "blocks": {
            "items": {
              "properties": {
                "status": {
                  "not": {
                    "const": "pending"
                  }
                }
              }
            }
          }
        }
      },
      "else": {
        "not": {
          "required": [
            "interrupt"
          ]
        },
        "properties": {
          "steps": {
            "items": {
              "properties": {
                "state": {
                  "not": {
                    "const": "awaiting_user"
                  }
                }
              }
            }
          }
        }
      }
    },
    {
      "$comment": "Client-generated user message ids double as idempotency keys, so they must be long enough to be unique (same rule as action ids). The former separate clientMessageId field was removed (see decisions D43).",
      "if": {
        "properties": {
          "role": {
            "const": "user"
          }
        },
        "required": [
          "role"
        ]
      },
      "then": {
        "properties": {
          "id": {
            "pattern": "^[A-Za-z0-9][A-Za-z0-9_.:-]{7,127}$"
          }
        }
      }
    },
    {
      "$comment": "Steps belong to assistant / system messages only.",
      "if": {
        "properties": {
          "role": {
            "const": "user"
          }
        },
        "required": [
          "role"
        ]
      },
      "then": {
        "not": {
          "required": [
            "steps"
          ]
        }
      }
    }
  ],
  "$defs": {
    "stepId": {
      "description": "Stable within its message; pairs step.started with step.finished (maps to AG-UI stepName).",
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$"
    },
    "stepLabel": {
      "description": "Host-written, user-facing description of the step, e.g. 'Checking this week's weather in Beijing'. Never a raw tool name, tool arguments or model output.",
      "type": "string",
      "minLength": 1,
      "maxLength": 60
    },
    "stepSummary": {
      "description": "Optional host-written one-line result note from a per-tool template, e.g. 'Found 3 tasks' or 'Weather service unavailable'. Never raw results or model output.",
      "type": "string",
      "minLength": 1,
      "maxLength": 120
    },
    "stepEndState": {
      "description": "succeeded / failed (affects only this step) / cancelled (still running or waiting when the user stopped the generation, or its interrupt expired). Waiting for the user is not an end state: the step is awaiting_user while the message is paused and returns to running when the answer arrives (docs/protocol.md 4.8).",
      "type": "string",
      "enum": [
        "succeeded",
        "failed",
        "cancelled"
      ]
    },
    "stepKind": {
      "description": "'delegate': the step hands work to a sub-agent; the sub-agent's own steps nest under it via parentStepId (collapsed by default in the process strip). Omitted for ordinary steps (a tool call or other unit of work). The sub-agent's internal name is never sent; the host-written label describes the delegation.",
      "type": "string",
      "enum": [
        "delegate"
      ]
    },
    "interruptId": {
      "description": "Opaque id of one interrupt (maps to AG-UI Interrupt.id). Unique within the message.",
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$"
    },
    "interrupt": {
      "description": "What a paused run is waiting for. The question itself is the interaction block (blockId) in the content; the step (stepId) is the one that asked and is awaiting_user. Expiry comes from the block's action.expiresAt.",
      "type": "object",
      "required": [
        "id",
        "stepId",
        "blockId",
        "reason"
      ],
